import type { AuditManifest, Finding, LlmOutput, ObligationAssessment, ReportLanguage } from '@odysseus/core';

/**
 * The analysis as generated by @odysseus/llm plus the provenance fields
 * analyze.ts writes alongside it to analyses/<timestamp>-<lang>.json.
 * generatedAt is typed as Date, not the ISO string the JSON file actually
 * stores, matching the same disk-vs-memory convention already used for
 * Finding.firstSeenAt/lastSeenAt: parsing the string is the caller's job
 * at the boundary, not this package's.
 */
export interface StoredAnalysis extends LlmOutput {
  auditId: string;
  language: ReportLanguage;
  model: string;
  temperature: number;
  generatedAt: Date;
  /** Computed once per audit by @odysseus/core's assessObligations and
   *  identical across every language's StoredAnalysis for that audit -
   *  the determination itself is language-neutral, only its report
   *  rendering (packages/report/src/template) varies by language.
   *  Optional: analyses generated before this milestone predate it. */
  obligationAssessment?: ObligationAssessment;
}

/** Milestone 8 addendum section 1.6: both tiers render from the same
 *  findings.json (section 1.2 - crawl scope is never tier-dependent), so
 *  tier is purely a report-rendering decision made at generation time,
 *  never stored on a Finding or threaded into @odysseus/core. Defaults
 *  to 'full' wherever it is optional, preserving every pre-milestone-8
 *  caller's existing behavior unchanged. */
export type ReportTier = 'screening' | 'full';

export interface GenerateReportInput {
  /** Used to resolve page screenshot files on disk (manifest.pages[].pageDir
   *  is relative to this directory). Never read for anything else: findings
   *  and the manifest itself are passed in already parsed, not re-read here. */
  auditDir: string;
  manifest: AuditManifest;
  /** Unfiltered: the full findings.json, not the LLM-filtered set, since
   *  the appendix must include minor findings the model never saw. */
  findings: Finding[];
  analysis: StoredAnalysis;
  /** Defaults to 'full' when omitted. */
  tier?: ReportTier;
}
